class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        cnt = 0
        res = []
        for i, c in queries:
            old = nums[i]
            if old != 0:
                if i > 0 and nums[i-1] == old:
                    cnt -= 1
                if i < n - 1 and nums[i+1] == old:
                    cnt -= 1
            nums[i] = c
            if i > 0 and nums[i-1] == c:
                cnt += 1
            if i < n - 1 and nums[i+1] == c:
                cnt += 1
            res.append(cnt)
        return res
