class Solution:
    def minimumSum(self, n: int, k: int) -> int:
        chosen = set()
        i = 1
        total = 0
        while len(chosen) < n:
            if (k - i) not in chosen:
                chosen.add(i)
                total += i
            i += 1
        return total
