class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True
        if 1 in nums:
            return False
        vals = list(set(nums))
        m = len(vals)
        if m == 1:
            return True
        mx = max(vals)
        spf = list(range(mx + 1))
        i = 2
        while i * i <= mx:
            if spf[i] == i:
                for j in range(i * i, mx + 1, i):
                    if spf[j] == j:
                        spf[j] = i
            i += 1
        parent = list(range(m + mx + 1))

        def find(x):
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        for idx, v in enumerate(vals):
            x = v
            while x > 1:
                p = spf[x]
                union(idx, m + p)
                while x % p == 0:
                    x //= p
        r = find(0)
        for idx in range(1, m):
            if find(idx) != r:
                return False
        return True
