class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True
        if 1 in nums:
            return False
        M = max(nums)
        spf = list(range(M + 1))
        i = 2
        while i * i <= M:
            if spf[i] == i:
                for j in range(i * i, M + 1, i):
                    if spf[j] == j:
                        spf[j] = i
            i += 1
        parent = list(range(M + 1))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        firsts = []
        seen = set()
        for v in set(nums):
            x = v
            first = spf[x]
            rf = find(first)
            while x > 1:
                p = spf[x]
                rp = find(p)
                if rp != rf:
                    parent[rp] = rf
                while x % p == 0:
                    x //= p
            firsts.append(first)
        root = find(firsts[0])
        for f in firsts:
            if find(f) != root:
                return False
        return True

