class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        pw = [0] * n
        p = 1 % k
        for i in range(n):
            pw[i] = p
            p = p * 10 % k
        w = []
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w.append(pw[i])
            else:
                w.append((pw[i] + pw[j]) % k)
        full = (1 << k) - 1
        reach = [0] * (h + 1)
        reach[h] = 1
        for i in range(h - 1, -1, -1):
            m = reach[i + 1]
            nm = 0
            lo = 1 if i == 0 else 0
            for d in range(lo, 10):
                c = d * w[i] % k
                if c == 0:
                    nm |= m
                else:
                    nm |= ((m << c) | (m >> (k - c))) & full
            reach[i] = nm
        res = []
        rem = 0
        for i in range(h):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                c = d * w[i] % k
                need = (-rem - c) % k
                if (reach[i + 1] >> need) & 1:
                    res.append(str(d))
                    rem = (rem + c) % k
                    break
        first = ''.join(res)
        if n % 2 == 1:
            return first + first[:-1][::-1]
