class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        M = 300
        D = 300  # diffs 0..299
        f = [None] * (M + 1)
        ans = 1
        for x in nums:
            cur = [1] * (D + 1)
            for d in range(D):
                best = 0
                v = x - d
                if v >= 1:
                    fv = f[v]
                    if fv is not None:
                        best = fv[d]
                v = x + d
                if d and v <= M:
                    fv = f[v]
                    if fv is not None and fv[d] > best:
                        best = fv[d]
                if best:
                    cur[d] = best + 1
            # suffix max
            for d in range(D - 2, -1, -1):
                if cur[d + 1] > cur[d]:
                    cur[d] = cur[d + 1]
            if cur[0] > ans:
                ans = cur[0]
            fx = f[x]
            if fx is None:
                f[x] = cur
            else:
                for d in range(D + 1):
                    if cur[d] > fx[d]:
                        fx[d] = cur[d]
        return ans

