    a = list(map(int, sys.stdin.read().split()))
    lines = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]

    @lru_cache(maxsize=None)
    def win(state):
        # returns True if player to move wins
        filled = sum(1 for c in state if c)
        p = 1 if filled % 2 == 0 else 2
        s = list(state)
        for i in range(9):
            if s[i] == 0:
                s[i] = p
                # check line
                done = False
                for x, y, z in lines:
                    if s[x] == p and s[y] == p and s[z] == p:
                        done = True
                        break
                if done:
                    return True
                if filled + 1 == 9:
                    sp = sum(a[k] for k in range(9) if s[k] == p)
                    so = sum(a[k] for k in range(9) if s[k] != p)
                    if sp > so:
                        return True
                else:
                    if not win(tuple(s)):
                        return True
                s[i] = 0
        return False

    print("Takahashi" if win(tuple([0]*9)) else "Aoki")

