import sys
from collections import deque
def main():
    data=sys.stdin.read().split()
    n=int(data[0]); S=data[1]; T=data[2]
    if S.count('B')!=T.count('B'):
        print(-1); return
    sm=0; tm=0
    for i,c in enumerate(S):
        if c=='B': sm|=1<<i
    for i,c in enumerate(T):
        if c=='B': tm|=1<<i
    SH=n+2
    start=(n<<SH)|sm
    target=(n<<SH)|tm
    if start==target:
        print(0); return
    dist={start:0}
    dq=deque([start])
    full=(1<<SH)-1
    while dq:
        st=dq.popleft()
        d=dist[st]
        e=st>>SH; m=st&full
        for x in range(n+1):
            if x==e or x==e+1 or x+1==e:
                continue
            b=(m>>x)&3
            nm=(m & ~(3<<x)) | (b<<e)
            ns=(x<<SH)|nm
            if ns not in dist:
                dist[ns]=d+1
                if ns==target:
                    print(d+1); return
                dq.append(ns)
    print(-1)
main()
