import sys
import numpy as np
def main():
    data=sys.stdin.read().split()
    N=int(data[0]); M=int(data[1]); S=data[2]
    MOD=998244353
    chars=sorted(set(S))
    other=26-len(chars)
    size=1<<N
    nxts=[]
    for c in chars:
        arr=np.zeros(size,dtype=np.int64)
        for st in range(size):
            dp=[0]*(N+1)
            for i in range(N):
                dp[i+1]=dp[i]+((st>>i)&1)
            nd=[0]*(N+1)
            for i in range(N):
                v=max(nd[i],dp[i+1],dp[i]+(1 if S[i]==c else 0))
                nd[i+1]=v
            ns=0
            for i in range(N):
                if nd[i+1]-nd[i]:
                    ns|=1<<i
            arr[st]=ns
        nxts.append(arr)
    cur=np.zeros(size,dtype=np.int64)
    cur[0]=1
    for _ in range(M):
        new=(cur*other)%MOD
        for arr in nxts:
            tmp=np.zeros(size,dtype=np.int64)
            np.add.at(tmp,arr,cur)
            new=(new+tmp)%MOD
        cur=new
    ans=[0]*(N+1)
    for st in range(size):
        ans[bin(st).count('1')]=(ans[bin(st).count('1')]+int(cur[st]))%MOD
    print(' '.join(map(str,ans)))
main()
