def main():
    data=sys.stdin.read().split()
    n=int(data[0]); m=int(data[1]); s=data[2]
    MOD=998244353
    chars=sorted(set(s))
    other=26-len(chars)
    F=1<<n
    trans=[]  # list per mask of list of next masks
    for mask in range(F):
        dp=[0]*(n+1)
        for j in range(n):
            dp[j+1]=dp[j]+((mask>>j)&1)
        nx=[]
        for c in chars:
            nd=[0]*(n+1)
            for j in range(n):
                if s[j]==c:
                    nd[j+1]=dp[j]+1
                else:
                    nd[j+1]=max(nd[j],dp[j+1])
            nm=0
            for j in range(n):
                if nd[j+1]-nd[j]:
                    nm|=1<<j
            nx.append(nm)
        trans.append(nx)
    cur=[0]*F
    cur[0]=1
    for _ in range(m):
        new=[0]*F
        for mask in range(F):
            v=cur[mask]
            if v==0: continue
            if other:
                new[mask]=(new[mask]+v*other)%MOD
            for nm in trans[mask]:
                new[nm]=(new[nm]+v)%MOD
        cur=new
    ans=[0]*(n+1)
    for mask in range(F):
        k=bin(mask).count('1')
