def main():
    data=sys.stdin.read().split()
    N=int(data[0]); M=int(data[1]); S=data[2]
    MOD=998244353
    chars=sorted(set(S))
    groups=[(c,1) for c in chars]
    other=26-len(chars)
    if other>0:
        groups.append(('#',other))
    size=1<<N
    trans=[]
    for mask in range(size):
        dp=[0]*(N+1)
        for i in range(1,N+1):
            dp[i]=dp[i-1]+((mask>>(i-1))&1)
        lst=[]
        for c,w in groups:
            new=[0]*(N+1)
            nm=0
            for i in range(1,N+1):
                v=new[i-1]
                if dp[i]>v: v=dp[i]
                if S[i-1]==c and dp[i-1]+1>v: v=dp[i-1]+1
                new[i]=v
                if v>new[i-1]: nm|=1<<(i-1)
            lst.append((nm,w))
        # merge same targets
        d={}
        for nm,w in lst:
            d[nm]=d.get(nm,0)+w
        trans.append(list(d.items()))
    cur=[0]*size
    cur[0]=1
    for _ in range(M):
        nxt=[0]*size
        for mask in range(size):
            v=cur[mask]
            if v:
                for nm,w in trans[mask]:
                    nxt[nm]+=v*w
        cur=[x%MOD for x in nxt]
    ans=[0]*(N+1)
    for mask in range(size):
        ans[bin(mask).count('1')]=(ans[bin(mask).count('1')]+cur[mask])%MOD
    print(' '.join(map(str,ans)))
