    MOD=998244353
    chars=sorted(set(s))
    classes=[(c,1) for c in chars]
    other=26-len(chars)
    if other>0:
        classes.append(('#',other))
    S=1<<n
    trans=[]  # trans[mask] = list of (nmask, mult)
    for mask in range(S):
        row=[0]*(n+1)
        for j in range(n):
            row[j+1]=row[j]+((mask>>j)&1)
        lst={}
        for c,mult in classes:
            new=[0]*(n+1)
            for j in range(1,n+1):
                v=new[j-1]
                if row[j]>v: v=row[j]
                if s[j-1]==c and row[j-1]+1>v: v=row[j-1]+1
                new[j]=v
            nm=0
            for j in range(n):
                if new[j+1]-new[j]:
                    nm|=1<<j
            lst[nm]=lst.get(nm,0)+mult
        trans.append(list(lst.items()))
    dp=[0]*S
    dp[0]=1
    for _ in range(m):
        nd=[0]*S
        for mask in range(S):
            v=dp[mask]
            if v:
                for nm,mu in trans[mask]:
                    nd[nm]+=v*mu
        dp=[x%MOD for x in nd]
    ans=[0]*(n+1)
    for mask in range(S):
        ans[bin(mask).count('1')]=(ans[bin(mask).count('1')]+dp[mask])%MOD
    print(' '.join(map(str,ans)))
